insert into public.knowledge_concept_prerequisites (concept_id, prerequisite_concept_id) select child.id, parent.id from public.knowledge_concepts child join public.capabilities c on c.id = child.capability_id join public.knowledge_concepts parent on parent.capability_id = c.id where c.code = 'finance' and child.concept_code = 'gross_margin' and parent.concept_code = 'gross_profit' on conflict do nothing;
